// ═══ APPROACH 1: BlockingQueue — simplest, production-ready! ═══
BlockingQueue<String> queue = new LinkedBlockingQueue<>(100);  // bounded!

// Producer:
queue.put("TRD-001");   // blocks if queue full! Auto-waits!

// Consumer:
String trade = queue.take();  // blocks if queue empty! Auto-waits!

// ZERO synchronization code! put/take handle everything internally.
// LinkedBlockingQueue: two locks (putLock + takeLock) → concurrent put+take!

// ═══ APPROACH 2: ReentrantLock + 2 Conditions — targeted wake-ups ═══
ReentrantLock lock = new ReentrantLock();
Condition notFull = lock.newCondition();   // producers wait here
Condition notEmpty = lock.newCondition();  // consumers wait here
Queue<String> buffer = new LinkedList<>();
int capacity = 100;

// Producer:
lock.lock();
try {
    while (buffer.size() >= capacity) notFull.await();  // WHILE! Not if!
    buffer.add("TRD-001");
    notEmpty.signal();  // wake ONE consumer (targeted!)
} finally { lock.unlock(); }

// Consumer:
lock.lock();
try {
    while (buffer.isEmpty()) notEmpty.await();  // WHILE! Not if!
    String trade = buffer.poll();
    notFull.signal();   // wake ONE producer (targeted!)
} finally { lock.unlock(); }

// ═══ APPROACH 3: synchronized + wait/notifyAll — classic ═══
synchronized (buffer) {
    while (buffer.size() >= capacity) buffer.wait();  // producer waits
    buffer.add("TRD-001");
    buffer.notifyAll();  // wakes ALL — consumers AND producers! Wasteful!
}

synchronized (buffer) {
    while (buffer.isEmpty()) buffer.wait();  // consumer waits
    String trade = buffer.poll();
    buffer.notifyAll();  // wakes ALL — wasteful!
}
// notifyAll wakes EVERYONE (50 producers + 50 consumers)
// Only 1 needs to act → 99 go back to sleep → CPU waste!
