package com.bank.prodcon;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import static org.assertj.core.api.Assertions.*;

class ProducerConsumerTest {

    // ═══ APPROACH 1: BlockingQueue (BEST — production-ready) ═══
    @Test
    void blockingQueue_producerConsumer() throws InterruptedException {
        BlockingQueue<String> queue = new LinkedBlockingQueue<>(5);
        List<String> consumed = new CopyOnWriteArrayList<>();
        int items = 20;
        CountDownLatch done = new CountDownLatch(items);

        // 3 producers:
        for (int p = 0; p < 3; p++) {
            final int pid = p;
            new Thread(() -> {
                try {
                    for (int i = 0; i < items / 3 + 1; i++) {
                        queue.put("P" + pid + "-" + i);  // blocks if full!
                    }
                } catch (InterruptedException e) { }
            }).start();
        }

        // 2 consumers:
        for (int c = 0; c < 2; c++) {
            new Thread(() -> {
                try {
                    while (done.getCount() > 0) {
                        String item = queue.poll(1, TimeUnit.SECONDS);
                        if (item != null) {
                            consumed.add(item);
                            done.countDown();
                        }
                    }
                } catch (InterruptedException e) { }
            }).start();
        }

        done.await(10, TimeUnit.SECONDS);
        assertThat(consumed.size()).isGreaterThanOrEqualTo(items);
    }

    // ═══ APPROACH 2: Lock + 2 Conditions (targeted) ═══
    static class BoundedBuffer<T> {
        private final Queue<T> queue = new LinkedList<>();
        private final int capacity;
        private final ReentrantLock lock = new ReentrantLock();
        private final Condition notFull = lock.newCondition();
        private final Condition notEmpty = lock.newCondition();

        BoundedBuffer(int capacity) { this.capacity = capacity; }

        void put(T item) throws InterruptedException {
            lock.lock();
            try {
                while (queue.size() >= capacity) notFull.await();
                queue.add(item);
                notEmpty.signal();
            } finally { lock.unlock(); }
        }

        T take() throws InterruptedException {
            lock.lock();
            try {
                while (queue.isEmpty()) notEmpty.await();
                T item = queue.poll();
                notFull.signal();
                return item;
            } finally { lock.unlock(); }
        }

        int size() { lock.lock(); try { return queue.size(); } finally { lock.unlock(); } }
    }

    @Test
    void lockConditions_producerConsumer() throws InterruptedException {
        BoundedBuffer<String> buffer = new BoundedBuffer<>(5);
        List<String> consumed = new CopyOnWriteArrayList<>();
        int items = 50;
        CountDownLatch produced = new CountDownLatch(items);
        CountDownLatch consumedAll = new CountDownLatch(items);

        // 5 producers
        for (int p = 0; p < 5; p++) {
            final int pid = p;
            new Thread(() -> {
                try {
                    for (int i = 0; i < items / 5; i++) {
                        buffer.put("P" + pid + "-" + i);
                        produced.countDown();
                    }
                } catch (InterruptedException e) { }
            }).start();
        }

        // 3 consumers
        for (int c = 0; c < 3; c++) {
            new Thread(() -> {
                try {
                    while (consumedAll.getCount() > 0) {
                        String item = buffer.take();
                        consumed.add(item);
                        consumedAll.countDown();
                    }
                } catch (InterruptedException e) { }
            }).start();
        }

        consumedAll.await(10, TimeUnit.SECONDS);
        assertThat(consumed).hasSize(items);  // all 50 consumed!
    }

    // ═══ APPROACH 3: synchronized + wait/notifyAll (classic) ═══
    @Test
    void waitNotifyAll_producerConsumer() throws InterruptedException {
        List<String> buffer = new ArrayList<>();
        int capacity = 5;
        List<String> consumed = new CopyOnWriteArrayList<>();
        CountDownLatch done = new CountDownLatch(10);

        // Producer
        new Thread(() -> {
            for (int i = 0; i < 10; i++) {
                synchronized (buffer) {
                    while (buffer.size() >= capacity) {
                        try { buffer.wait(); } catch (InterruptedException e) { return; }
                    }
                    buffer.add("TRD-" + i);
                    buffer.notifyAll();  // wakes ALL — consumers AND producers!
                }
            }
        }).start();

        // Consumer
        new Thread(() -> {
            for (int i = 0; i < 10; i++) {
                synchronized (buffer) {
                    while (buffer.isEmpty()) {
                        try { buffer.wait(); } catch (InterruptedException e) { return; }
                    }
                    consumed.add(buffer.remove(0));
                    buffer.notifyAll();
                    done.countDown();
                }
            }
        }).start();

        done.await(10, TimeUnit.SECONDS);
        assertThat(consumed).hasSize(10);
    }
}
